/// <reference types="react-scripts" />

declare module "*.css" {
    const content: string;
    export default content;
}

declare module "*.png" {
    const content: string;
    export default content;
}

declare module "*.jpg" {
    const content: string;
    export default content;
}

declare module "*.jpeg" {
    const content: string;
    export default content;
}

declare module "*.svg" {
    const content: string;
    export default content;
}

declare module "*.json" {
    const content: unknown;
    export default content;
}

declare module "*.pdf" {
    const content: string;
    export default content;
}

